messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low-Poly Humanoid Treadmill</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 10px;
            left: 10px;
            color: white;
            font-family: sans-serif;
            font-size: 14px;
            background: rgba(0,0,0,0.5);
            padding: 5px 10px;
            border-radius: 4px;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">Cycle: <span id="cycle-label">STILL</span></div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const CYCLE_DURATION = 10; // seconds
        const STILL_TIME = 2;
        const WALK_TIME = 3;
        const RUN_TIME = 3;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 5, 15);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 1.5, 5);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(-5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- Materials ---
        const skinMat = new THREE.MeshStandardMaterial({ color: 0xe0ac69, flatShading: true });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0x4a90e2, flatShading: true });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x3e4a5e, flatShading: true });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0x2c3e50, flatShading: true });
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x2c3e50, flatShading: true });

        // --- Humanoid Construction ---
        const humanoid = new THREE.Group();

        // Helper to create limb
        function createLimb(width, height, depth, material, x, y, z) {
            const geo = new THREE.BoxGeometry(width, height, depth);
            const mesh = new THREE.Mesh(geo, material);
            mesh.position.set(x, y, z);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // Pivot points (Joints)
        const hipJoint = new THREE.Group();
        hipJoint.position.set(0, 1.0, 0); // Height of hips

        const spineJoint = new THREE.Group();
        spineJoint.position.set(0, 0.4, 0); // Top of hips

        // Torso
        const torso = createLimb(0.4, 0.5, 0.2, shirtMat, 0, 0.25, 0);
        spineJoint.add(torso);

        // Head
        const head = createLimb(0.25, 0.25, 0.25, skinMat, 0, 0.65, 0);
        spineJoint.add(head);

        // Arms
        const leftShoulder = new THREE.Group();
        leftShoulder.position.set(0.25, 0.4, 0);
        const rightShoulder = new THREE.Group();
        rightShoulder.position.set(-0.25, 0.4, 0);

        const leftUpperArm = createLimb(0.1, 0.3, 0.1, shirtMat, 0, -0.15, 0);
        const rightUpperArm = createLimb(0.1, 0.3, 0.1, shirtMat, 0, -0.15, 0);

        leftShoulder.add(leftUpperArm);
        rightShoulder.add(rightUpperArm);

        const leftLowerArm = createLimb(0.08, 0.3, 0.08, skinMat, 0, -0.3, 0);
        const rightLowerArm = createLimb(0.08, 0.3, 0.08, skinMat, 0, -0.3, 0);
        leftUpperArm.add(leftLowerArm);
        rightUpperArm.add(rightLowerArm);

        spineJoint.add(leftShoulder);
        spineJoint.add(rightShoulder);

        // Legs
        const leftHipJoint = new THREE.Group();
        leftHipJoint.position.set(0.12, 0, 0);
        const rightHipJoint = new THREE.Group();
        rightHipJoint.position.set(-0.12, 0, 0);

        const leftThigh = createLimb(0.12, 0.4, 0.12, pantsMat, 0, -0.2, 0);
        const rightThigh = createLimb(0.12, 0.4, 0.12, pantsMat, 0, -0.2, 0);

        leftHipJoint.add(leftThigh);
        rightHipJoint.add(rightThigh);

        const leftShinJoint = new THREE.Group();
        leftShinJoint.position.set(0, -0.4, 0);
        const rightShinJoint = new THREE.Group();
        rightShinJoint.position.set(0, -0.4, 0);

        const leftShin = createLimb(0.1, 0.4, 0.1, pantsMat, 0, -0.2, 0);
        const rightShin = createLimb(0.1, 0.4, 0.1, pantsMat, 0, -0.2, 0);

        leftShinJoint.add(leftShin);
        rightShinJoint.add(rightShin);

        const leftFoot = createLimb(0.1, 0.1, 0.2, shoeMat, 0, -0.4, 0.05);
        const rightFoot = createLimb(0.1, 0.1, 0.2, shoeMat, 0, -0.4, 0.05);
        leftShinJoint.add(leftFoot);
        rightShinJoint.add(rightFoot);

        hipJoint.add(leftHipJoint);
        hipJoint.add(rightHipJoint);
        hipJoint.add(spineJoint);

        // Belt
        const belt = createLimb(0.42, 0.05, 0.22, beltMat, 0, 0, 0);
        hipJoint.add(belt);

        scene.add(humanoid);

        // --- Treadmill ---
        const treadmillGroup = new THREE.Group();

        // Base
        const baseGeo = new THREE.BoxGeometry(2, 0.1, 1.2);
        const baseMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const base = new THREE.Mesh(baseGeo, baseMat);
        base.position.y = -0.05;
        base.receiveShadow = true;
        treadmillGroup.add(base);

        // Belt
        const beltGeo = new THREE.BoxGeometry(1.8, 0.05, 1);
        const beltMeshMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const beltMesh = new THREE.Mesh(beltGeo, beltMeshMat);
        beltMesh.position.y = 0.025;
        beltMesh.receiveShadow = true;
        treadmillGroup.add(beltMesh);

        // Side rails
        const railGeo = new THREE.BoxGeometry(1.8, 0.6, 0.1);
        const railMat = new THREE.MeshStandardMaterial({ color: 0x444444 });
        const leftRail = new THREE.Mesh(railGeo, railMat);
        leftRail.position.set(0, 0.3, 0.55);
        treadmillGroup.add(leftRail);
        const rightRail = new THREE.Mesh(railGeo, railMat);
        rightRail.position.set(0, 0.3, -0.55);
        treadmillGroup.add(rightRail);

        // Console
        const consoleGeo = new THREE.BoxGeometry(0.8, 0.8, 0.4);
        const consoleMat = new THREE.MeshStandardMaterial({ color: 0x666666 });
        const consoleMesh = new THREE.Mesh(consoleGeo, consoleMat);
        consoleMesh.position.set(0, 0.5, -0.4);
        treadmillGroup.add(consoleMesh);

        scene.add(treadmillGroup);

        // --- Animation Logic ---
        const cycleLabel = document.getElementById('cycle-label');

        function animate() {
            requestAnimationFrame(animate);

            const time = Date.now() / 1000;
            const cycleTime = time % CYCLE_DURATION;

            // Determine Phase
            let phase = 'STILL';
            let phaseTime = 0;

            if (cycleTime < STILL_TIME) {
                phase = 'STILL';
                phaseTime = cycleTime;
            } else if (cycleTime < STILL_TIME + WALK_TIME) {
                phase = 'WALK';
                phaseTime = cycleTime - STILL_TIME;
            } else if (cycleTime < STILL_TIME + WALK_TIME + RUN_TIME) {
                phase = 'RUN';
                phaseTime = cycleTime - STILL_TIME - WALK_TIME;
            } else {
                phase = 'STILL';
                phaseTime = cycleTime - (STILL_TIME + WALK_TIME + RUN_TIME);
            }

            cycleLabel.innerText = phase;

            // Reset poses
            // Left Leg
            leftHipJoint.rotation.x = 0;
            leftShinJoint.rotation.x = 0;
            // Right Leg
            rightHipJoint.rotation.x = 0;
            rightShinJoint.rotation.x = 0;
            // Arms
            leftShoulder.rotation.x = 0;
            rightShoulder.rotation.x = 0;
            leftLowerArm.rotation.x = 0;
            rightLowerArm.rotation.x = 0;
            // Body
            spineJoint.rotation.x = 0;
            hipJoint.position.y = 1.0;

            // Treadmill belt speed visual (simple texture offset simulation via scale/pos or just rotation if we had a texture)
            // For low poly, let's just move the belt mesh slightly to simulate movement
            let beltSpeed = 0;
            if (phase === 'WALK') beltSpeed = 0.05;
            if (phase === 'RUN') beltSpeed = 0.15;

            // Simple visual trick for belt movement: pulse the width slightly or move a texture. 
            // Since we don't have a texture, let's just rely on the limbs.

            if (phase === 'STILL') {
                // Subtle breathing
                const breath = Math.sin(time * 2) * 0.02;
                hipJoint.position.y = 1.0 + breath;
                torso.scale.y = 1 + breath * 2;
            } 
            else if (phase === 'WALK') {
                // Walk Animation
                const speed = 3; // Radians per second
                const stride = 0.5; // Max rotation in radians
                const kneeBend = 0.4;
                const armSwing = 0.4;

                // Legs
                const legAngle = Math.sin(time * speed) * stride;
                leftHipJoint.rotation.x = legAngle;
                rightHipJoint.rotation.x = -legAngle;

                // Knees bend when leg swings back (negative rotation)
                leftShinJoint.rotation.x = Math.max(0, -leftHipJoint.rotation.x * 1.5);
                rightShinJoint.rotation.x = Math.max(0, -rightHipJoint.rotation.x * 1.5);

                // Arms (Opposite to legs)
                const armAngle = Math.sin(time * speed) * armSwing;
                leftShoulder.rotation.x = -armAngle;
                rightShoulder.rotation.x = armAngle;

                // Elbows bend slightly
                leftLowerArm.rotation.x = Math.max(0, leftShoulder.rotation.x * 0.5);
                rightLowerArm.rotation.x = Math.max(0, rightShoulder.rotation.x * 0.5);

                // Body Bob
                const bob = Math.abs(Math.sin(time * speed)) * 0.05;
                hipJoint.position.y = 1.0 + bob;
                // Slight lean
                spineJoint.rotation.x = 0.05;

            } 
            else if (phase === 'RUN') {
                // Run Animation
                const speed = 5; // Faster
                const stride = 0.9; // Larger swing
                const kneeBend = 0.8;
                const armSwing = 0.8;

                // Legs
                const legAngle = Math.sin(time * speed) * stride;
                leftHipJoint.rotation.x = legAngle;
                rightHipJoint.rotation.x = -legAngle;

                // Knees bend more
                leftShinJoint.rotation.x = Math.max(0, -leftHipJoint.rotation.x * 1.8);
                rightShinJoint.rotation.x = Math.max(0, -rightHipJoint.rotation.x * 1.8);

                // Arms
                const armAngle = Math.sin(time * speed) * armSwing;
                leftShoulder.rotation.x = -armAngle;
                rightShoulder.rotation.x = armAngle;

                // Elbows bend more
                leftLowerArm.rotation.x = Math.max(0, leftShoulder.rotation.x * 0.8);
                rightLowerArm.rotation.x = Math.max(0, rightShoulder.rotation.x * 0.8);

                // Body Bob (More pronounced)
                const bob = Math.abs(Math.sin(time * speed)) * 0.15;
                hipJoint.position.y = 1.0 + bob;
                // Forward Lean
                spineJoint.rotation.x = 0.2;
            }

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
